create table if not exists public.tour_packages (
  id text primary key,
  slug text not null unique,
  name text not null check (char_length(trim(name)) between 1 and 120),
  state text not null check (char_length(trim(state)) between 1 and 80),
  categories text[] not null default '{}',
  hero_image text not null,
  package_data jsonb not null,
  is_published boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.customer_requests (
  request_id uuid primary key default gen_random_uuid(),
  submission_id uuid not null unique,
  request_type text not null check (request_type in ('cab_booking', 'tour_quote', 'temple_tour', 'cab_attachment')),
  customer_name text not null check (char_length(trim(customer_name)) between 1 and 120),
  mobile text not null check (mobile ~ '^[6-9][0-9]{9}$'),
  request_data jsonb not null check (octet_length(request_data::text) <= 30000),
  contact_consent boolean not null check (contact_consent),
  status text not null default 'New' check (status in ('New', 'Reviewing', 'Quoted', 'Contacted', 'Confirmed', 'Rejected', 'Completed')),
  quoted_amount numeric(12,2) check (quoted_amount is null or quoted_amount >= 0),
  quote_notes text not null default '' check (char_length(quote_notes) <= 5000),
  admin_notes text not null default '' check (char_length(admin_notes) <= 5000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create or replace function public.touch_site_data_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin new.updated_at = now(); return new; end;
$$;
drop trigger if exists tour_packages_updated_at on public.tour_packages;
create trigger tour_packages_updated_at before update on public.tour_packages
for each row execute function public.touch_site_data_updated_at();
drop trigger if exists customer_requests_updated_at on public.customer_requests;
create trigger customer_requests_updated_at before update on public.customer_requests
for each row execute function public.touch_site_data_updated_at();

alter table public.tour_packages enable row level security;
revoke all on public.tour_packages from anon, authenticated;
grant select on public.tour_packages to anon, authenticated;
drop policy if exists "public can read published tour packages" on public.tour_packages;
create policy "public can read published tour packages" on public.tour_packages
for select to anon, authenticated using (is_published or public.is_driver_admin());
grant insert, update, delete on public.tour_packages to authenticated;
drop policy if exists "driver admins manage tour packages" on public.tour_packages;
create policy "driver admins manage tour packages" on public.tour_packages
for all to authenticated using (public.is_driver_admin()) with check (public.is_driver_admin());

alter table public.customer_requests enable row level security;
revoke all on public.customer_requests from anon, authenticated;
grant select, update on public.customer_requests to authenticated;
drop policy if exists "driver admins read customer requests" on public.customer_requests;
create policy "driver admins read customer requests" on public.customer_requests
for select to authenticated using (public.is_driver_admin());
drop policy if exists "driver admins update customer requests" on public.customer_requests;
create policy "driver admins update customer requests" on public.customer_requests
for update to authenticated using (public.is_driver_admin()) with check (public.is_driver_admin());


