values
  ('kodaikanal', '/tour-packages/kodaikanal', 'Kodaikanal', 'Tamil Nadu', ARRAY['Hill Station Getaways', 'Family Holidays', 'Weekend Trips', 'Outstation Road Trips']::text[], '/tours/generated/hd/kodaikanal.jpg', '{"id":"kodaikanal","name":"Kodaikanal","shortName":"Kodaikanal","region":"Palani Hills","slug":"/tour-packages/kodaikanal","routeSlug":"/chennai-to-kodaikanal-cab","hero":"/tours/generated/hd/kodaikanal.jpg","alt":"High-definition scenic view of Kodaikanal Lake and Palani Hills","duration":"Suggested 2–3 days","durationDays":"2–3","category":["Hill Station Getaways","Family Holidays","Weekend Trips","Outstation Road Trips"],"summary":"A relaxed hill escape with lakeside time, forested viewpoints and cool-weather walks.","overview":"Kodaikanal brings together wooded hills, a star-shaped lake, walking paths and waterfalls in the Palani Hills. Choose a gentle sightseeing loop or leave more time for lake-side breaks and viewpoints. The suggested plan can be adjusted around weather and access on your travel dates.","highlights":["Kodai Lake","Coaker’s Walk","Pillar Rocks","Silver Cascade"],"attractions":[{"name":"Kodai Lake","description":"Spend time around the lake and choose from activities available locally on the day.","image":"/tours/kodaikanal/stops/kodaikanal-lake.jpg","alt":"AI-generated illustration of Kodaikanal Lake","credit":"AI-generated illustrative artwork; not a documentary photograph"},{"name":"Coaker’s Walk","description":"A scenic promenade for an easy stroll and hill-country views when conditions are clear.","image":"/tours/kodaikanal/stops/coakers-walk.jpg","alt":"AI-generated illustration of Coaker’s Walk in Kodaikanal","credit":"AI-generated illustrative artwork; not a documentary photograph"},{"name":"Pillar Rocks","description":"Tall rock formations and a viewing area among the forested hills.","image":"/tours/kodaikanal/stops/pillar-rocks.jpg","alt":"AI-generated illustration of Pillar Rocks in Kodaikanal","credit":"AI-generated illustrative artwork; not a documentary photograph"},{"name":"Silver Cascade","description":"A roadside waterfall stop; water flow varies by season and rainfall.","image":"/tours/kodaikanal/stops/silver-cascade.jpg","alt":"AI-generated illustration of Silver Cascade near Kodaikanal","credit":"AI-generated illustrative artwork; not a documentary photograph"}],"itinerary":[{"day":"Day 1","title":"Town and lake circuit","text":"A relaxed day around Kodaikanal town and its lake.","places":[{"name":"Silver Cascade Falls","image":"/tours/kodaikanal/stops/silver-cascade.jpg","description":"A famous waterfall near the Kodaikanal approach road."},{"name":"Kurinji Andavar Temple","image":"/tours/kodaikanal/stops/kurinji-andavar-temple.jpg","description":"A Murugan temple in peaceful surroundings."},{"name":"Coaker’s Walk","image":"/tours/kodaikanal/stops/coakers-walk.jpg","description":"A popular paved walking path with valley views."},{"name":"Bryant Park","image":"/tours/kodaikanal/stops/bryant-park.jpg","description":"A landscaped botanical garden."},{"name":"Kodaikanal Lake","image":"/tours/kodaikanal/stops/kodaikanal-lake.jpg","description":"Enjoy boating, cycling and lakeside scenery, subject to local availability."},{"name":"Upper Lake View","image":"/tours/kodaikanal/stops/upper-lake-view.jpg","description":"A roadside viewpoint overlooking the lake."}]},{"day":"Day 2","title":"Famous viewpoints circuit","text":"A scenic route through Kodaikanal’s forest-side viewpoints.","places":[{"name":"Moir Point","image":"/tours/kodaikanal/stops/moir-point.jpg","description":"A popular viewpoint on the forest-side route."},{"name":"Pine Forest","image":"/tours/kodaikanal/stops/pine-forest.jpg","description":"Tall pine trees and scenic photography spots."},{"name":"Guna Caves","image":"/tours/kodaikanal/stops/guna-caves.jpg","description":"Famous rocky scenery and forest surroundings; access may be restricted."},{"name":"Pillar Rocks","image":"/tours/kodaikanal/stops/pillar-rocks.jpg","description":"Three towering rock formations."},{"name":"Green Valley View","image":"/tours/kodaikanal/stops/green-valley-view.jpg","description":"A well-known valley viewpoint."},{"name":"Caps Fly Valley View","image":"/tours/kodaikanal/stops/caps-fly-valley-view.jpg","description":"A scenic stop on local sightseeing routes, subject to access."}]},{"day":"Day 3","title":"Poombarai and countryside","text":"Explore village and countryside scenery beyond the town.","places":[{"name":"Poombarai Village","image":"/tours/kodaikanal/stops/poombarai-village.jpg","description":"A hillside village with terraced landscapes."},{"name":"Kuzhanthai Velappar Temple","image":"/tours/kodaikanal/stops/kuzhanthai-velappar-temple.jpg","description":"A historic Murugan temple near Poombarai."},{"name":"Mannavanur Lake","image":"/tours/kodaikanal/stops/mannavanur-lake.jpg","description":"A peaceful countryside lake and grassland area."}]}],"suitable":["Swift Dzire · up to 4 passengers","Ertiga · up to 6 passengers"],"included":["Private cab for the agreed itinerary","Driver and fuel for the confirmed route","Pickup and drop as agreed"],"excluded":["Accommodation and meals","Entry tickets, activities and parking","Tolls and charges outside the confirmed quote"],"faqs":[["Can I change the suggested itinerary?","Yes. Share the places and pace you prefer; the team will check the route and provide a revised quote."],["Is the fare fixed on this page?","No package price is displayed because the final quote depends on dates, route, duration, vehicle and availability."]],"sourceLinks":[{"label":"Incredible India · Kodaikanal overview","href":"https://www.prod.incredibleindia.gov.in/content/incredible-india-v2/en/destinations/madurai/kodaikanal.html"}],"state":"Tamil Nadu"}'::jsonb, true, 0),
  ('ooty', '/tour-packages/ooty', 'Ooty & Coonoor', 'Tamil Nadu', ARRAY['Hill Station Getaways', 'Family Holidays', 'Outstation Road Trips']::text[], '/tours/generated/hd/ooty.jpg', '{"id":"ooty","name":"Ooty & Coonoor","shortName":"Ooty","region":"Nilgiris","slug":"/tour-packages/ooty","routeSlug":"/chennai-to-ooty-cab","hero":"/tours/generated/hd/ooty.jpg","alt":"High-definition Nilgiri tea hills near Ooty and Coonoor","duration":"Suggested 3–4 days","durationDays":"3–4","category":["Hill Station Getaways","Family Holidays","Outstation Road Trips"],"summary":"Tea country, botanical gardens, mountain views and optional heritage railway planning.","overview":"Ooty and nearby Coonoor offer gardens, tea landscapes and highland viewpoints in the Nilgiris. This road-trip plan uses flexible sightseeing blocks so the day can adapt to weather, traffic and attraction access.","highlights":["Ooty Lake","Government Botanical Gardens","Doddabetta Peak","Tea gardens","Nilgiri Mountain Railway"],"attractions":[{"name":"Ooty Lake","description":"A popular town-side lake; local activities and access may vary.","image":"/tours/ooty/ooty-lake-crop.jpg","alt":"AI-generated illustration of Ooty Lake","credit":"AI-generated illustrative artwork; not a documentary photograph"},{"name":"Government Botanical Gardens","description":"A landscaped garden maintained by Tamil Nadu’s Horticulture Department.","image":"/tours/ooty/botanical-gardens-crop.jpg","alt":"AI-generated illustration of the Ooty Botanical Gardens","credit":"AI-generated illustrative artwork; not a documentary photograph"},{"name":"Doddabetta Peak","description":"A Nilgiri viewpoint known for wide views over surrounding hills and forests.","image":"/tours/ooty/doddabetta-peak-crop.jpg","alt":"AI-generated illustration of Doddabetta Peak","credit":"AI-generated illustrative artwork; not a documentary photograph"},{"name":"Coonoor tea country","description":"Tea-growing landscapes and viewpoints around Coonoor; stop access d