  ('rameswaram', '/tour-packages/rameswaram', 'Rameswaram', 'Tamil Nadu', ARRAY['Family Holidays', 'Outstation Road Trips', 'Coastal Getaways']::text[], '/tours/generated/hd/rameswaram.jpg', '{"id":"rameswaram","name":"Rameswaram","shortName":"Rameswaram","region":"Ramanathapuram Coast","slug":"/tour-packages/rameswaram","hero":"/tours/generated/hd/rameswaram.jpg","alt":"High-definition Pamban Bridge over the turquoise sea near Rameswaram","duration":"Suggested 3 days","durationDays":"3","category":["Family Holidays","Outstation Road Trips","Coastal Getaways"],"summary":"A coastal pilgrimage journey with temple time, island sights and a flexible return plan.","overview":"Rameswaram combines a major pilgrimage site with coastal and island sightseeing. Build in time for temple visits and allow the schedule to flex around local guidance, visitor access, weather and road conditions.","highlights":["Ramanathaswamy Temple","Agni Theertham","Pamban Bridge","Dhanushkodi","Dr. A.P.J. Abdul Kalam Memorial"],"attractions":[{"name":"Ramanathaswamy Temple","description":"A major Shiva pilgrimage shrine, known for its architecture and sacred water tanks. Follow current temple guidance for visitor access.","image":"/tours/rameswaram/ramanathaswamy-temple-crop.jpg","alt":"AI-generated illustration of Ramanathaswamy Temple","credit":"AI-generated illustrative artwork; not a documentary photograph"},{"name":"Pamban Bridge","description":"The celebrated bridge links Rameswaram Island with the mainland; view access and stopping rules can change.","image":"/tours/rameswaram/pamban-bridge-crop.jpg","alt":"AI-generated illustration of Pamban Bridge","credit":"AI-generated illustrative artwork; not a documentary photograph"},{"name":"Dr. A.P.J. Abdul Kalam Memorial","description":"A memorial dedicated to the former President of India. Confirm visitor timings and access before your visit.","image":"/tours/rameswaram/apj-memorial-crop.jpg","alt":"AI-generated illustration of the A.P.J. Abdul